export function logPageView(data: { path: string; userAgent: string }) {
  console.log('[analytics] page view', data)
}

import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from '@/app/utils'

export default async function Home() {
  const userAgent = (await headers()).get('user-agent') || 'unknown'
  const path = '/'

  after(() => {
    logPageView({ path, userAgent })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Page view logged in the background.</p>
    </main>
  )
}
